import os
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeDocumentRequest
from azure.core.credentials import AzureKeyCredential

def extract_receipt_data(image_path):
    # Azure Document Intelligence setup
    endpoint = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, 
        credential=AzureKeyCredential(key)
    )

    with open(image_path, "rb") as image_file:
        image_data = image_file.read()

    # Analyze the receipt using prebuilt invoice model
    poller = document_intelligence_client.begin_analyze_document(
        analyze_request=AnalyzeDocumentRequest(bytes_source=image_data),
        api_version="2023-02-28-preview",
        model_id="prebuilt-invoice"
    )

    result = poller.result()

    # Extract structured data
    extracted_data = {
        "merchant": None,
        "tax": None,
        "total": None,
        "items": []
    }

    # Parse merchant name
    if result.documents:
        doc = result.documents[0]
        for field in doc.fields:
            if field.name == "VendorName":
                extracted_data["merchant"] = field.value_string
            elif field.name == "TaxAmount":
                extracted_data["tax"] = field.value_float
            elif field.name == "TotalAmount":
                extracted_data["total"] = field.value_float

    # Parse line items
    if "LineItems" in doc.fields:
        line_items = doc.fields["LineItems"]
        if hasattr(line_items, 'value_array'):
            for item in line_items.value_array:
                item_data = {}
                for field in item.value_object:
                    if field.name == "Description":
                        item_data["description"] = field.value_string
                    elif field.name == "Quantity":
                        item_data["quantity"] = field.value_float
                    elif field.name == "UnitPrice":
                        item_data["unit_price"] = field.value_float
                    elif field.name == "TotalAmount":
                        item_data["total_amount"] = field.value_float
                extracted_data["items"].append(item_data)

    return extracted_data
